   300	/**
   301	 * There are 2 possibilities that we can receive via pusher for a user's typing/leaving status:
   302	 * 1. The "new" way from New Expensify is passed as {[login]: Boolean} (e.g. {yuwen@expensify.com: true}), where the value
   303	 * is whether the user with that login is typing/leaving on the report or not.
   304	 * 2. The "old" way from e.com which is passed as {userLogin: login} (e.g. {userLogin: bstites@expensify.com})
   305	 *
   306	 * This method makes sure that no matter which we get, we return the "new" format
   307	 */
   308	function getNormalizedStatus(typingStatus: Pusher.UserIsTypingEvent | Pusher.UserIsLeavingRoomEvent): ReportUserIsTyping {
   309	    let normalizedStatus: ReportUserIsTyping;
   310	
   311	    if (typingStatus.userLogin) {
   312	        normalizedStatus = {[typingStatus.userLogin]: true};
   313	    } else {
   314	        normalizedStatus = typingStatus;
   315	    }
   316	
   317	    return normalizedStatus;
   318	}
